<?php require_once __DIR__.'/../config/auth.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT * FROM usuarios WHERE id=? AND tipo='aluno'");$s->execute([$id]);$u=$s->fetch();if(!$u)exit('Aluno não encontrado.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('UPDATE usuarios SET nome=?,email=?,telefone=?,ra=?,turma=?,curso=?,status=? WHERE id=?');$s->execute([trim($_POST['nome']),trim($_POST['email']),trim($_POST['telefone']),trim($_POST['ra']),trim($_POST['turma']),trim($_POST['curso']),$_POST['status'],$id]);flash('success','Dados do aluno atualizados.');redirect('admin/alunos.php');}$loans=db()->prepare('SELECT e.*,l.titulo FROM emprestimos e JOIN livros l ON l.id=e.livro_id WHERE e.usuario_id=? ORDER BY e.created_at DESC');$loans->execute([$id]);$pageTitle='Editar aluno';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><form class="panel" method="post"><?=csrf_field()?><div class="form-grid"><?php foreach(['nome'=>'Nome','email'=>'E-mail','telefone'=>'Telefone','ra'=>'RA','turma'=>'Turma'] as $f=>$label):?><div class="form-group"><label><?=$label?></label><input <?=$f==='email'?'type="email"':''?> required name="<?=$f?>" value="<?=e($u[$f])?>"></div><?php endforeach;?><div class="form-group"><label>Curso</label><select required name="curso"><option value="">Selecione o curso</option><?php foreach(['Ensino Fundamental 1','Ensino Fundamental 2','Ensino Médio','Ensino Médio Técnico'] as $curso):?><option <?=$u['curso']===$curso?'selected':''?>><?=e($curso)?></option><?php endforeach;?></select></div><div class="form-group"><label>Status</label><select name="status"><option <?=$u['status']==='ativo'?'selected':''?> value="ativo">Ativo</option><option <?=$u['status']==='bloqueado'?'selected':''?> value="bloqueado">Bloqueado</option></select></div></div><button class="btn">Salvar</button></form><section class="panel"><h2>Histórico de empréstimos</h2><?php foreach($loans as $l):?><p><?=e($l['titulo'])?> — <span class="badge"><?=e(loan_status($l))?></span></p><?php endforeach;?></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
